/* ---------------- Spell catalog (5e core spell list) ----------------
   One entry per spell. Summaries are short paraphrases of the effect, not
   the full rules text; enough to pick a spell and remember what it does;
   the sheet's spell sheet lets players add their own notes. */
var SCHOOLS = {
  Abj:"Abjuration", Con:"Conjuration", Div:"Divination", Enc:"Enchantment",
  Evo:"Evocation", Ill:"Illusion", Nec:"Necromancy", Tra:"Transmutation"
};

/* s(level, school, castingTime, range, components, duration, classes, summary, opts)
   classes is a comma list; concentration is derived from the duration
   text; opts = {ritual:true, material:"…"} for the rare extras. */
function s(level, school, castingTime, range, components, duration, classes, summary, opts){
  opts = opts || {};
  return {
    level: level,
    school: SCHOOLS[school],
    castingTime: castingTime,
    range: range,
    components: components,
    material: opts.material || "",
    duration: duration,
    concentration: /^Concentration/.test(duration),
    ritual: !!opts.ritual,
    classes: classes.split(","),
    summary: summary
  };
}

